-- OWNER-CLOSURE-IMPLEMENT-01: retained identity/history; account-wide application denial.
-- Filename generated by `supabase migration new owner_closure_01` (CLI 2.120.0, no DB).
BEGIN;

CREATE TABLE monjez_private.owner_account_closures (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE RESTRICT,
  closed_at timestamptz NOT NULL DEFAULT transaction_timestamp()
);
ALTER TABLE monjez_private.owner_account_closures ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE monjez_private.owner_account_closures
  FROM PUBLIC, anon, authenticated, service_role;

-- Preserve the existing Auth-state check, signature, ACL and all its existing consumers.
CREATE OR REPLACE FUNCTION monjez_private.actor_is_active()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $guard$
  SELECT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = (SELECT auth.uid()) AND u.deleted_at IS NULL
      AND (u.banned_until IS NULL OR u.banned_until <= statement_timestamp())
      AND NOT EXISTS (
        SELECT 1 FROM monjez_private.owner_account_closures c WHERE c.user_id = u.id
      )
  );
$guard$;

CREATE FUNCTION public.close_owner_account()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $closure$
DECLARE
  v_uid uuid := auth.uid();
  v_auth_active boolean;
BEGIN
  -- This self-service entry has no trusted-service exception or target user argument.
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' OR v_uid IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'authentication_required';
  END IF;

  -- Serialize self-closure calls without mutating Auth or any financial/public row.
  -- Independent live Auth check must precede the narrow already-closed exception.
  SELECT u.deleted_at IS NULL
      AND (u.banned_until IS NULL OR u.banned_until <= statement_timestamp())
    INTO v_auth_active
    FROM auth.users u WHERE u.id = v_uid FOR UPDATE;
  IF v_auth_active IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'account_inactive';
  END IF;

  IF EXISTS (SELECT 1 FROM monjez_private.owner_account_closures c WHERE c.user_id = v_uid) THEN
    -- Constant own-status acknowledgement only; no protected data read or reopening.
    RETURN jsonb_build_object('status', 'closed');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.tenants t
    JOIN public.user_roles r ON r.tenant_id = t.id AND r.user_id = v_uid
      AND r.role = 'owner'::public.app_role
    WHERE t.owner_user_id = v_uid
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'owner_required';
  END IF;

  -- The marker itself is the one auditable closure event; public history stays intact.
  INSERT INTO monjez_private.owner_account_closures(user_id) VALUES (v_uid);
  RETURN jsonb_build_object('status', 'closed');
END;
$closure$;

REVOKE ALL ON FUNCTION public.close_owner_account()
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.close_owner_account() TO authenticated;

COMMENT ON TABLE monjez_private.owner_account_closures IS
  'Account-wide application closure event. Retains identity and all store/financial references. No automatic erasure/reopening; personal-data retention policy remains separate.';
COMMENT ON FUNCTION public.close_owner_account() IS
  'Authenticated self-owner closure only. Constant idempotent own acknowledgement after independent live Auth check; no target ID, public data mutation or reopening.';

COMMIT;
